// Contoh JPEG untuk uji jembatan gPhoto2 (24x24, baseline dan progresif) + pembuat varian yang meniru kamera sungguhan.
const BASE = Buffer.from("", "base64");
const PROG = Buffer.from("", "base64");
const seg = (marker, payload) => { const h = Buffer.alloc(4); h[0] = 0xff; h[1] = marker; h.writeUInt16BE(payload.length + 2, 2); return Buffer.concat([h, payload]); };
const insertAfterSoi = (jpg, s) => Buffer.concat([jpg.subarray(0, 2), s, jpg.subarray(2)]);
/** Tambah komentar sampai ukuran minimal (live view asli ratusan KB; backend menolak frame < 500 byte). */
const padded = (jpg, size = 2000) => insertAfterSoi(jpg, seg(0xfe, Buffer.alloc(Math.max(0, size - jpg.length - 4), 0x41)));
/** JPEG yang EXIF-nya memuat thumbnail JPEG lengkap (ada FFD8...FFD9 di dalam APP1): pemecah naif akan salah potong. */
const withExifThumb = (jpg) => insertAfterSoi(jpg, seg(0xe1, Buffer.concat([Buffer.from("Exif\0\0"), padded(BASE, 600)])));
const variants = () => [padded(BASE), withExifThumb(padded(BASE, 1500)), padded(PROG)];
module.exports = { BASE, PROG, padded, withExifThumb, variants };
